document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const i=document.getElementById("childcare-form"),t=document.getElementById("childcare-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const a=parseInt(document.getElementById("children-capacity").value),o=parseFloat(document.getElementById("renovation-cost").value),r=parseFloat(document.getElementById("equipment-cost").value),l=parseFloat(document.getElementById("licensing-cost").value),d=parseFloat(document.getElementById("monthly-fee").value),c=parseFloat(document.getElementById("occupancy-rate").value),p=parseFloat(document.getElementById("additional-services").value),u=parseFloat(document.getElementById("rent").value),v=parseFloat(document.getElementById("staff-salaries").value),g=parseFloat(document.getElementById("food-costs").value),m=parseFloat(document.getElementById("utilities").value),h=parseFloat(document.getElementById("other-expenses").value);if(a<=0||d<=0||c<=0)return t.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const $=o+r+l,f=Math.round(a*(c/100)),w=f*d,b=f*p,y=w+b,E=12*y,k=u+v+g+m+h,I=12*k,F=y-k,M=E-I,x=M/E*100,B=$/M,C=M/$*100,P=E/f,A=I/f,D=M/f,L=Math.round(f/Math.max(1,Math.floor(v/800)));let R="info";M<0?R="warning":x>25&&(R="success");let S="info";c<75?S="warning":c>90&&(S="success");let O="info";L>8?O="warning":L<=6&&(O="success"),t.innerHTML=`\n        <div class="business-plan-results">\n          <h3>👶 Childcare Center Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n($),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(F),`Margin: ${e(x)}`,R)}\n            ${s("⏱️ Payback Period",`${B.toFixed(1)} years`,`ROI: ${e(C)}`,B<=4?"success":"warning")}\n            ${s("👥 Enrollment",`${f} children`,`${e(c)} of capacity`,S)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Facility renovation & setup</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment & furniture</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licensing & permits</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n($)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Tuition fees (${f} children × ${n(d)})</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (enrichment, extended care)</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(y)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Facility rent/lease</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff salaries</span>\n                  <span>${n(v)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Food & meal costs</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(h)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>👶 Per Child Metrics</h6>\n              <div class="metric-subtitle">\n                Annual revenue: <strong>${n(P)}</strong><br>\n                Annual expenses: <strong>${n(A)}</strong><br>\n                Annual profit: <strong>${n(D)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${O}">\n              <h6>👥 Staff-to-Child Ratio</h6>\n              <div class="metric-subtitle">\n                Children per caregiver: <strong>${L}:1</strong><br>\n                Recommended: <strong>6:1 - 8:1</strong><br>\n                Care quality: <strong>${L<=6?"Excellent":L<=8?"Good":"Needs improvement"}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${F>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(M)}</strong><br>\n                Weekly profit: <strong>${n(M/52)}</strong><br>\n                Daily profit: <strong>${n(M/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Scaling Potential</h6>\n              <div class="metric-subtitle">\n                Maximum capacity: <strong>${a} children</strong><br>\n                Current enrollment: <strong>${f} children</strong><br>\n                Growth opportunity: <strong>${a-f} spaces</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${x<20?"<li>⚠️ Low profitability. Consider increasing tuition rates or reducing costs.</li>":""}\n              ${c<80?"<li>👥 Low enrollment. Improve marketing and service quality.</li>":""}\n              ${B>5?"<li>⏰ Long payback period. Optimize startup costs or increase revenue.</li>":""}\n              ${L>8?"<li>👥 High child-to-staff ratio. Consider adding caregivers for better quality.</li>":""}\n              ${c>95?"<li>✅ Excellent enrollment! Consider expansion or rate increases.</li>":""}\n              ${x>30?"<li>🎉 Outstanding profitability! Consider opening additional locations.</li>":""}\n              <li>🎨 Add specialized programs: art, music, foreign language classes.</li>\n              <li>🌍 Implement bilingual or multilingual education programs.</li>\n              <li>📱 Use parent communication apps for daily updates and photos.</li>\n              <li>🏃 Offer extended hours and weekend care services.</li>\n              <li>👨‍⚕️ Provide specialist consultations: pediatric nurse, speech therapist.</li>\n              <li>🎪 Host family events and seasonal celebrations.</li>\n              <li>📚 Develop partnerships with local elementary schools.</li>\n              <li>💻 Integrate educational technology and STEAM programs.</li>\n              <li>🏆 Pursue quality certifications and accreditation.</li>\n              <li>🚌 Add transportation services for school-age programs.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.childcareBusinessData={"Capacity (children)":a,"Actual Enrollment":f,"Total Investment ($)":$,"Annual Revenue ($)":E,"Annual Expenses ($)":I,"Annual Profit ($)":M,"Monthly Profit ($)":F,"Profit Margin (%)":x,"Annual ROI (%)":C,"Payback Period (years)":B,"Enrollment Rate (%)":c,"Revenue per Child ($)":P,"Monthly Tuition ($)":d}}),window.downloadCSV=function(){if(!window.childcareBusinessData)return;const n=Object.entries(window.childcareBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="childcare-center-business-plan.csv",s.click()}});